selector_to_html = {"a[href=\"#dynamic-circuits\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Dynamic circuits<a class=\"headerlink\" href=\"#dynamic-circuits\" title=\"Link to this heading\">#</a></h2><p>Builders are candidate-stable pending API-owner approval, while dynamic\nexecution and backend assessment remain experimental. Local dynamic noise is\nlimited to one-wire bit-flip channels and independent readout confusion, and\nprovider-noise execution fails closed. No real IQM QPU task has been used; the\nBraket IQM integration was validated through the real SDK serializer and a\nmocked task contract only.</p>", "a[href=\"#boundary\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Boundary<a class=\"headerlink\" href=\"#boundary\" title=\"Link to this heading\">#</a></h2><p>Conversion does not install dependencies, sandbox third-party Python, or\ncertify provider hardware. External framework objects never enter the\ncompiler, PyTorch runtime, Torch-FL, accelerator, or QPU layers.</p>", "a[href=\"#qiskit\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Qiskit<a class=\"headerlink\" href=\"#qiskit\" title=\"Link to this heading\">#</a></h2><p>Certified against Qiskit 2.0.x/2.5.x with Aer 0.17.x for operations, wire order,\nstatevectors, classical bits, arithmetic parameter expressions, custom unitaries\nup to three qubits, and round trips. Functions, powers, other symbolic\noperations, and control flow fail closed; named or multiple registers require\nexplicit lossy flattening.</p><p>The Qiskit Aer bridge executes one fully bound, single-batch circuit on local CPU\nAer and returns an owned <code class=\"docutils literal notranslate\"><span class=\"pre\">ExecutionResult</span></code> with explicit wire order, seed, and\nCPU thread controls.</p>", "a[href=\"#cirq-and-cuda-q\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Cirq and CUDA-Q<a class=\"headerlink\" href=\"#cirq-and-cuda-q\" title=\"Link to this heading\">#</a></h2><p>Cirq support covers the contract gate subset, contiguous <code class=\"docutils literal notranslate\"><span class=\"pre\">LineQubit</span></code> indices,\nbound real parameters, and an explicit qubit order; the Simulator bridge\nexecutes one fully bound circuit locally. CUDA-Q export is deliberately\none-way, does not execute the kernel, and reverses bit axes explicitly because\nCUDA-Q treats wire zero as least-significant.</p>", "a[href=\"#interoperability\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Interoperability<a class=\"headerlink\" href=\"#interoperability\" title=\"Link to this heading\">#</a></h1><p>External frameworks connect through one candidate-stable, framework-neutral\nadapter protocol under <code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.ecosystem</span></code>. The default registry stores\nimport-safe descriptors and loads an implementation only when requested, so\nimporting an adapter never imports its dependency.</p>", "a[href=\"#pennylane\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">PennyLane<a class=\"headerlink\" href=\"#pennylane\" title=\"Link to this heading\">#</a></h2><p>PennyLane 0.44.1/0.45.1 on Python 3.11 or newer supports static <code class=\"docutils literal notranslate\"><span class=\"pre\">QuantumScript</span></code>\nconversion with complex128 semantics. QNodes, device execution, shots,\nmeasurements, trainable parameters, and arbitrary wire labels without explicit\nflattening are out of scope for v1. The Lightning bridge executes one fully\nbound circuit on local CPU <code class=\"docutils literal notranslate\"><span class=\"pre\">lightning.qubit</span></code> and returns an owned\n<code class=\"docutils literal notranslate\"><span class=\"pre\">ExecutionResult</span></code>; it does not support gradients, noise models, dynamic\ncircuits, automatic routing, GPU, or fallback.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
